def filterCoordinate (γ : Γ) : FilterNullSpace 𝕜 F →L[𝕜] 𝕜 :=
  LinearMap.mkContinuous
    { toFun := fun x => x γ
      map_add' := by intros; rfl
      map_smul' := by intros; rfl }
    1 (fun x => by simpa using x.norm_apply_le γ)

